// src/forkop/tabs/settings/sectionChoices.ts
function isDownloadSectionAction(action) {
  switch (action) {
    case "connection":
    case "proxy":
    case "outbound":
    case "vpn":
      return true;
    default:
      return false;
  }
}
function refreshDownloadSectionChoices(option2) {
  const sections = option2.map?.data?.state?.values?.[FORKOP_UCI_PACKAGE] ?? {};
  option2.keylist = [];
  option2.vallist = [];
  for (const secName in sections) {
    const sec = sections[secName];
    if (sec[".type"] === "section" && sec.enabled !== "0" && isDownloadSectionAction(sec.action)) {
      option2.value(secName, sec.label || secName);
    }
  }
}
function configureDownloadSectionOption(option2, sectionOption) {
  option2.default = "";
  option2.rmempty = false;
  option2.cfgvalue = function(section_id) {
    return uci.get(FORKOP_UCI_PACKAGE, section_id, sectionOption) || "";
  };
  option2.load = function(section_id) {
    refreshDownloadSectionChoices(this);
    const value = this.cfgvalue(section_id);
    keepUnavailableSectionChoice(this, value);
    return value;
  };
  option2.write = function(section_id, value) {
    const normalized = value ? `${value}`.trim() : "";
    if (normalized) {
      uci.set(FORKOP_UCI_PACKAGE, section_id, sectionOption, normalized);
    } else {
      uci.unset(FORKOP_UCI_PACKAGE, section_id, sectionOption);
    }
  };
  option2.remove = function(section_id) {
    uci.unset(FORKOP_UCI_PACKAGE, section_id, sectionOption);
  };
  option2.validate = function(_section_id, value) {
    return value ? true : _("Select a section");
  };
}
function configureDownloadViaProxyFlag(option2, sectionOption) {
  option2.default = "0";
  option2.rmempty = false;
  option2.write = function(section_id, value) {
    const enabled = value === "1" || value === true;
    uci.set(FORKOP_UCI_PACKAGE, section_id, this.option, enabled ? "1" : "0");
    if (!enabled) {
      uci.unset(FORKOP_UCI_PACKAGE, section_id, sectionOption);
    }
  };
}

// src/validators/validateStaticHosts.ts
function lineFields(line, offset) {
  const commentIndex = line.search(/\/\/|#/);
  const body = commentIndex >= 0 ? line.slice(0, commentIndex) : line;
  const fields = [];
  const pattern = /[^\s]+/g;
  let match;
  while ((match = pattern.exec(body)) !== null) {
    fields.push({
      value: match[0],
      start: offset + match.index,
      end: offset + match.index + match[0].length
    });
  }
  return fields;
}
function analyzeStaticHosts(text2) {
  const value = `${text2 || ""}`;
  const annotations = [];
  const errors = [];
  let offset = 0;
  const reject = (field, message) => {
    annotations.push({ start: field.start, end: field.end, message });
    errors.push(`${field.value}: ${message}`);
  };
  for (const line of value.split("\n")) {
    const fields = lineFields(line, offset);
    offset += line.length + 1;
    if (!fields.length) {
      continue;
    }
    const [address, ...domains] = fields;
    if (!isIPv4(address.value) && !isIPv6(address.value)) {
      reject(address, _("Invalid IP address"));
    }
    if (!domains.length) {
      reject(address, _("Add at least one domain"));
      continue;
    }
    for (const domain of domains) {
      const ascii = asciiHostname(domain.value.toLowerCase());
      if (!ascii || !validAsciiDomain(ascii, false)) {
        reject(domain, _("Invalid domain address"));
      }
    }
  }
  if (!errors.length) {
    return { valid: true, message: _("Valid"), annotations: [] };
  }
  annotations.sort((left, right) => left.start - right.start);
  return { valid: false, message: errors.join("\n"), annotations };
}

